export type TokenStatus = 'ACTIVE' | 'DEGRADED' | 'EXPIRED' | 'ROTATING' | 'REVOKED';

export type RotationEvent = 
  | 'AUTO_REFRESH' 
  | 'MANUAL_REFRESH' 
  | 'JITTER_BACKOFF' 
  | 'ROTATION_FAIL' 
  | 'REVOKE';

export interface TokenSession {
  accessToken: string;
  refreshToken: string;
  tokenType: string;
  scope: string;
  expiresInSec: number;
  remainingSec: number;
  issuedAt: number;
  expiresAt: number;
  kid: string;
  jti: string;
  generation: number;
  status: TokenStatus;
}

export interface RotationLog {
  id: string;
  timestamp: string;
  event: RotationEvent;
  previousJti: string;
  newJti: string;
  latencyMs: number;
  jitterOffsetMs: number;
  httpStatus: number;
  traceId: string;
}

export interface EngineMetrics {
  totalRotations: number;
  successfulRotations: number;
  failedRotations: number;
  avgLatencyMs: number;
  jitterBackoffEvents: number;
  tokenDegradationAlerts: number;
}

