/**
 * @fileoverview ChaseTokenRefreshEngine - Segment 1
 * Core Types, Interfaces, and State Management Architecture
 */

export type TokenStatus = 'ACTIVE' | 'DEGRADED' | 'EXPIRED' | 'ROTATING' | 'REVOKED';

export type RotationEvent = 
  | 'AUTO_REFRESH' 
  | 'MANUAL_REFRESH' 
  | 'JITTER_BACKOFF' 
  | 'ROTATION_FAIL' 
  | 'REVOKE';

export interface TokenSession {
  accessToken: string;
  refreshToken: string;
  tokenType: string;
  scope: string;
  expiresInSec: number;
  remainingSec: number;
  issuedAt: number;
  expiresAt: number;
  kid: string;
  jti: string;
  generation: number;
  status: TokenStatus;
}

export interface RotationLog {
  id: string;
  timestamp: string;
  event: RotationEvent;
  previousJti: string;
  newJti: string;
  latencyMs: number;
  jitterOffsetMs: number;
  httpStatus: number;
  traceId: string;
}

export interface EngineMetrics {
  totalRotations: number;
  successfulRotations: number;
  failedRotations: number;
  avgLatencyMs: number;
  jitterBackoffEvents: number;
  tokenDegradationAlerts: number;
}

export interface EngineConfig {
  tokenTtlSeconds: number;
  renewalWindowThresholdPct: number;
  enableJitter: boolean;
  jitterRangeMs: number;
  simulatedFailureRate: number;
}

export interface EngineContextType {
  session: TokenSession;
  metrics: EngineMetrics;
  logs: RotationLog[];
  config: EngineConfig;
  isRotating: boolean;
  isEngineRunning: boolean;
  updateConfig: (newConfig: Partial<EngineConfig>) => void;
  executeRefreshToken: (isManual?: boolean) => Promise<void>;
  handleRevoke: () => void;
  handleResetSession: () => void;
}

export const ChaseEngineContext = createContext<EngineContextType | undefined>(undefined);

export const useChaseEngine = () => {
  const context = useContext(ChaseEngineContext);
  if (!context) {
    throw new Error('useChaseEngine must be used within a ChaseTokenRefreshEngineProvider');
  }
  return context;
};

export const INITIAL_METRICS: EngineMetrics = {
  totalRotations: 0,
  successfulRotations: 0,
  failedRotations: 0,
  avgLatencyMs: 42,
  jitterBackoffEvents: 0,
  tokenDegradationAlerts: 0,
};

export const DEFAULT_CONFIG: EngineConfig = {
  tokenTtlSeconds: 30,
  renewalWindowThresholdPct: 25,
  enableJitter: true,
  jitterRangeMs: 450,
  simulatedFailureRate: 0,
};

export const generateTraceId = (): string => {
  return Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
};

export const createInitialSession = (ttl: number): TokenSession => {
  const now = Date.now();
  return {
    accessToken: `cctk_${Math.random().toString(36).substring(2, 15)}_${Math.random().toString(36).substring(2, 15)}`,
    refreshToken: `ccrf_${Math.random().toString(36).substring(2, 15)}_${Math.random().toString(36).substring(2, 15)}`,
    tokenType: 'Bearer',
    scope: 'card loyalty:pwp:enrollment merchant:read',
    expiresInSec: ttl,
    remainingSec: ttl,
    issuedAt: now,
    expiresAt: now + ttl * 1000,
    kid: 'jpmc-cc-auth-2025-v1',
    jti: `jti_chase_${Math.random().toString(36).substring(2, 10)}`,
    generation: 1,
    status: 'ACTIVE',
  };
};

