                  {JSON.stringify({ sub: 'partner-app-pwp-client-78912', aud: 'https://api.chase.com/card/loyalty', jti: session.jti, scope: session.scope, iat: Math.floor(session.issuedAt / 1000), exp: Math.floor(session.expiresAt / 1000), rot_gen: session.generation }, null, 2)}
